using System;
using DeadSpin.Runtime.Bootstrap;
using DeadSpin.Runtime.Interaction;
using DeadSpin.Runtime.Player;
using DeadSpin.Runtime.UI;
using UnityEngine;

namespace DeadSpin.Runtime.Environment
{
    /// <summary>
    /// Assembles the complete Phase 1 scene content into the currently open scene: casino room,
    /// player rig, GameSession and HUD, with every reference wired. The editor menu calls this and
    /// saves the result, so the scene is generated by code instead of hand-edited YAML.
    /// </summary>
    public static class PrototypeSceneFactory
    {
        public const float PlayerHeight = 1.75f;
        public const float EyeHeight = 1.62f;

        public sealed class Result
        {
            public GameSession Session;
            public GameObject Player;
            public Camera Camera;
            public PrototypeCasinoBuilder.Result Casino;
        }

        /// <param name="persistMaterial">Optional callback that saves generated materials as assets (editor only).</param>
        public static Result Build(Func<Material, Material> persistMaterial = null)
        {
            var materials = new PrototypeMaterials(persistMaterial);
            var result = new Result { Casino = PrototypeCasinoBuilder.Build(materials) };

            result.Player = BuildPlayer(result.Casino.PlayerSpawn, out result.Camera);

            var sessionObject = new GameObject("GameSession");
            result.Session = sessionObject.AddComponent<GameSession>();
            result.Session.SetPlayerSpawn(result.Casino.PlayerSpawn);
            sessionObject.AddComponent<PrototypeHud>();

            return result;
        }

        private static GameObject BuildPlayer(Transform spawn, out Camera camera)
        {
            var player = new GameObject("Player");
            player.transform.SetPositionAndRotation(spawn.position, spawn.rotation);

            var controller = player.AddComponent<CharacterController>();
            controller.height = PlayerHeight;
            controller.radius = 0.3f;
            controller.center = new Vector3(0f, PlayerHeight * 0.5f, 0f);
            controller.stepOffset = 0.3f;
            controller.slopeLimit = 45f;
            controller.skinWidth = 0.03f;

            player.AddComponent<PlayerInputReader>();
            player.AddComponent<FirstPersonController>();

            var pivot = new GameObject("CameraPivot").transform;
            pivot.SetParent(player.transform, false);
            pivot.localPosition = new Vector3(0f, EyeHeight, 0f);

            var cameraObject = new GameObject("PlayerCamera");
            cameraObject.tag = "MainCamera";
            cameraObject.transform.SetParent(pivot, false);
            camera = cameraObject.AddComponent<Camera>();
            camera.nearClipPlane = 0.03f;
            camera.farClipPlane = 60f;
            camera.fieldOfView = 70f;
            camera.clearFlags = CameraClearFlags.SolidColor;
            camera.backgroundColor = Color.black;
            cameraObject.AddComponent<AudioListener>();
            cameraObject.AddComponent<CameraFocus>();
            cameraObject.AddComponent<Interactor>();

            // PlayerLook needs its pivot before Awake runs, so it is added inactive-safe via a helper.
            PlayerLook look = AddPlayerLook(player, pivot);
            if (look == null) Debug.LogError("[PrototypeSceneFactory] Failed to configure PlayerLook.");
            return player;
        }

        private static PlayerLook AddPlayerLook(GameObject player, Transform pivot)
        {
            // Deactivate while wiring so Awake sees the serialized pivot (matters when built in Play mode).
            bool wasActive = player.activeSelf;
            player.SetActive(false);
            var look = player.AddComponent<PlayerLook>();
            look.SetPitchPivot(pivot);
            player.SetActive(wasActive);
            return look;
        }
    }
}
